function th(it,cls=""){const k=LBR.push(it)-1;const src=I[it[3]];const st=`background-image:url(${src});${it[4]?`background-position:${it[4]};background-size:${it[5]}`:""}`;return `<button class="th ${cls}" data-lb="${k}" style="${st}" aria-label="View picture: ${it[2]}"></button>`}
