function hlInit(el,act){const hl=el.querySelector(".hl"),its=[...el.querySelectorAll(".li")];let cur=act;const to=i=>{const d=Math.abs(i-cur);hl.style.transitionDuration=(0.14+0.07*Math.min(d,6))+"s";hl.style.height=its[i].offsetHeight+"px";hl.style.top=its[i].offsetTop+"px";cur=i};to(act);const sel=()=>+el.querySelector("[aria-selected=true]").dataset.i;its.forEach((b,i)=>{b.addEventListener("mouseenter",()=>to(i));b.addEventListener("focus",()=>to(i))});el.addEventListener("mouseleave",()=>to(sel()))}
