function svcDetail(){const f=F[sv];LBR=[];return `<div class="panel sc"><div class="kick">${f.n}</div><h2>${f.lead}</h2><p class="lead">${f.d}</p><div class="row">${th([f.n,f.d,f.c,f.i,f.v?"v":""])}<span style="color:var(--mu);font-size:14px">Select the picture to view it with its caption.</span></div><h3>Who it is for</h3><p>${f.who}</p><h3>Problems we fix</h3><ul class="wl" style="columns:1">${f.p.map(x=>`<li>${x}</li>`).join("")}</ul><h3>How it works</h3><p>${f.hi}</p>${dg(f.hp)}<h3>How we build it</h3><div class="ph">${f.b.map((x,i)=>`<div><span>STEP ${i+1}</span><b>${x[0]}</b><p>${x[1]}</p></div>`).join("")}</div><h3>What you get</h3><ul class="wl">${f.g.map(x=>`<li>${x}</li>`).join("")}</ul><p style="font-size:14px;color:var(--mu);margin-top:14px"><b style="color:var(--tx)">Typical technology:</b> ${f.t}</p><h3>In detail</h3>${f.s.map(s=>`<div class="sub">${th(s,"s")}<div><b>${s[0]}</b><p>${s[1]}</p></div></div>`).join("")}<h3>Questions we get</h3>${f.q.map(q=>`<details><summary>${q[0]}</summary><p>${q[1]}</p></details>`).join("")}<div class="cb"><div><b>Ready to talk about ${f.n.toLowerCase()}?</b><p>Tell us what is slow, broken or missing. We reply with questions, not a sales pitch.</p></div><button class="btn o" data-go="contact" data-pre="${f.id}">Request an assessment</button></div></div>`}
