const FORMSPREE_ENDPOINT="https://formspree.io/f/mkjrgpya";

async function submitToFormspree(form){
  const res=await fetch(FORMSPREE_ENDPOINT,{method:"POST",body:new FormData(form),headers:{Accept:"application/json"}});
  if(!res.ok)throw new Error("Formspree request failed with status "+res.status);
  return res;
}

document.addEventListener("submit",async e=>{
  const form=e.target;
  if(form.id==="cf"){
    e.preventDefault();
    const btn=form.querySelector('button[type="submit"]');
    const ok=document.getElementById("ok");
    const label=btn.textContent;
    btn.disabled=true;btn.textContent="Sending...";ok.textContent="";
    try{
      await submitToFormspree(form);
      document.getElementById("cwrap").innerHTML=`<div class="panel"><div class="kick">Message sent</div><h2 style="font-size:32px">Thank you. Your enquiry is on its way.</h2><p class="lead2">We have received your message and will reply to the email address you gave us. If you need to add anything, write to <a href="mailto:hello@mericloud.tech" style="color:var(--pr);font-weight:600">hello@mericloud.tech</a>.</p></div>`;
    }catch(err){
      ok.textContent="Sorry, the form could not be sent. Please try again or email hello@mericloud.tech.";
      ok.style.color="var(--ac)";
      btn.disabled=false;btn.textContent=label;
    }
  }else if(form.id==="nlf"){
    e.preventDefault();
    const btn=form.querySelector('button[type="submit"]');
    const label=btn.textContent;
    btn.disabled=true;btn.textContent="Subscribing...";
    try{
      await submitToFormspree(form);
      form.innerHTML='<span style="font-size:14px;color:var(--mu)">Thanks. You are subscribed.</span>';
    }catch(err){
      form.innerHTML='<span style="font-size:14px;color:var(--ac)">Sorry, the subscription could not be sent. Please try again.</span>';
    }
  }
});

