const rm=matchMedia("(prefers-reduced-motion:reduce)").matches;
function zoom(){const w=document.getElementById("wrap");if(!w)return;const st=document.getElementById("stage"),world=document.getElementById("world"),ht=document.getElementById("heroT"),ring=document.getElementById("ring");
let sp=0,ra=0;const k=Math.min(1,innerWidth/1500),upd=()=>{ra=0;if(!document.getElementById("wrap"))return;const r=w.getBoundingClientRect(),tp=rm?1:Math.max(0,Math.min(1,-r.top/(w.offsetHeight-innerHeight)));sp=rm?tp:sp+(tp-sp)*.09;if(Math.abs(tp-sp)<.0004)sp=tp;else if(!ra)ra=requestAnimationFrame(upd);const p=sp,e=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;const tz=760*(1-e)-250*e,rx=16*(1-e)+6*e;world.style.transform=`scale(${1+(k-1)*e}) translate3d(0,0,${tz}px) rotateX(${rx}deg) rotateY(${(1-e)*-8}deg)`;ht.style.opacity=Math.max(0,1-p*3.4);ht.style.pointerEvents=p>.3?"none":"auto";ring.style.opacity=Math.max(0,(p-.6)*3);world.querySelectorAll("[data-f]").forEach(t=>t.style.opacity=Math.min(1,Math.max(0,(p-.25)*2.2)))};
const onS=()=>{if(!ra)ra=requestAnimationFrame(upd)};if(window.__zs){removeEventListener("scroll",window.__zs);removeEventListener("resize",window.__zs)}window.__zs=onS;addEventListener("scroll",onS,{passive:true});addEventListener("resize",onS);upd()}
document.addEventListener("click",e=>{const t=e.target.closest("[data-go],[data-f],[data-lb],.li");if(!t){if(e.target.closest("#lb"))closeLb();return}
if(t.dataset.go){if(t.dataset.pre)pre=t.dataset.pre;return go(t.dataset.go)}if(t.dataset.f!==undefined){sv=+t.dataset.f;return go("services")}
if(t.dataset.lb!==undefined)return openLb(LBR[+t.dataset.lb]);
if(t.classList.contains("li")){const l=t.parentElement,i=+t.dataset.i;l.querySelectorAll(".li").forEach(b=>b.setAttribute("aria-selected",b==t));const det=document.getElementById("det");if(l.id=="sl"){sv=i;det.innerHTML=svcDetail()}else if(l.id=="fl"){fl=i;det.innerHTML=stepDetail(FL,i)}else if(l.id=="pl"){pr=i;det.innerHTML=PDET(i)}else if(LS[l.id]){LS[l.id](i)}}});
function openLb(it){const lb=document.getElementById("lb");const m=it[4]=="v"?`<video src="${I.vid}" autoplay muted loop playsinline></video>`:`<img src="${I[it[3]]}" alt="${it[2]}">`;lb.innerHTML=`<figure>${m}<figcaption>${it[2]}</figcaption></figure>`;lb.classList.add("on")}
function closeLb(){document.getElementById("lb").classList.remove("on")}
addEventListener("keydown",e=>{if(e.key=="Escape")closeLb()});
document.addEventListener("click",e=>{const j=e.target.closest("[data-j]");if(j){const el=document.getElementById(j.dataset.j);if(el)el.scrollIntoView({behavior:"smooth",block:"start"})}});

