(function(){const b=document.getElementById("ck");let s=null;try{s=localStorage.getItem("mck")}catch(x){}if(!s)b.style.display="flex";const set=v=>{try{localStorage.setItem("mck",v)}catch(x){}b.style.display="none"};document.getElementById("ck1").onclick=()=>set("all");document.getElementById("ck2").onclick=()=>set("essential")})();
